package com.estoqueinteligente.auth;
import java.time.Instant;import jakarta.persistence.*;
@Entity @Table(name="users")public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=150)private String name;@Column(nullable=false,unique=true,length=180)private String email;@Column(nullable=false,length=100)private String password;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private UserRole role;@Column(nullable=false)private boolean active=true;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public UserRole getRole(){return role;}public void setRole(UserRole v){role=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
